package org.firstinspires.ftc.teamcode.TeleOp.Testing;

import com.pedropathing.api.Paths;
import com.pedropathing.api.PoseFactory;
import com.pedropathing.drivetrain.DrivePowers;
import com.pedropathing.follower.Follower;
import com.pedropathing.follower.ManualDrive;
import com.pedropathing.math.Pose;
import com.qualcomm.robotcore.eventloop.opmode.OpMode;
import com.qualcomm.robotcore.eventloop.opmode.TeleOp;
import com.qualcomm.robotcore.hardware.DcMotor;
import com.qualcomm.robotcore.util.ElapsedTime;

import org.firstinspires.ftc.robotcore.external.navigation.AngleUnit;
import org.firstinspires.ftc.robotcore.external.navigation.DistanceUnit;
import org.firstinspires.ftc.robotcore.external.navigation.Pose2D;
import org.firstinspires.ftc.teamcode.TeleOp.GoBildaPinpointDriver;
import org.firstinspires.ftc.teamcode.TeleOp.OpModeStorage;
import org.firstinspires.ftc.teamcode.TeleOp.StateMachines.BerthaIntakeSMV2;
import org.firstinspires.ftc.teamcode.TeleOp.StateMachines.BerthaLauncherSMPIDF;
import org.firstinspires.ftc.teamcode.TeleOp.StateMachines.BerthaWindmillSM;
import org.firstinspires.ftc.teamcode.pedro.Constants;

@TeleOp(name = "Bertha Pedro Drive Test and Auto Drive", group = "Bertha")
public class BerthaDriverOrientedAutoDrive extends OpMode {

    public DcMotor rearLeft = null;
    public DcMotor rearRight = null;
    public DcMotor frontLeft = null;
    public DcMotor frontRight = null;

    GoBildaPinpointDriver odo; // Declare OpMode member for the Odometry Computer


    private ElapsedTime runtime = new ElapsedTime();

    double frontLeftV;
    double rearLeftV;
    double frontRightV;
    double rearRightV;

    double forward;
    double right;
    double clockwise;

    double denominator;
    double temp;
    double side;

    double currentAngle;

    double baselauncherRPM = 0;

    private Follower follower;

    // This variable scales the joystick power.
    // A value of 1.0 means full power.
    private double powerMultiplier = 1.0;
    private final PoseFactory p = PoseFactory.degrees();
    private final Pose Launch_Spot = p.of(55, 8, 270);
    private static final double Stick_cancel = 0.3; //for cancelling the autodrive
    private boolean autoDriving = false;
    private boolean prevA = false;
    @Override
    public void init() {

        // Initialize the hardware variables. Note that the strings used here must correspond
        // to the names assigned during the robot configuration step on the DS or RC devices.

        odo = hardwareMap.get(GoBildaPinpointDriver.class,"pinpoint");

        /*
        Set the odometry pod positions relative to the point that the odometry computer tracks around.
        The X pod offset refers to how far sideways from the tracking point the
        X (forward) odometry pod is. Left of the center is a positive number,
        right of center is a negative number. the Y pod offset refers to how far forwards from
        the tracking point the Y (strafe) odometry pod is. forward of center is a positive number,
        backwards is a negative number.
         */
        odo.setOffsets(32.5, -37.5, DistanceUnit.MM); //these are tuned for 3110-0002-0001 Product Insight #1

        /*
        Set the kind of pods used by your robot. If you're using goBILDA odometry pods, select either
        the goBILDA_SWINGARM_POD, or the goBILDA_4_BAR_POD.
        If you're using another kind of odometry pod, uncomment setEnc.
        odo.setEncoderResolution(GoBildaPinpointDriver.GoBildaOdometryPods.goBILDA_4_BAR_POD);
        //odo.setEncoderResolution(13.26291192, DistanceUnit.MM);


        /*
        Set the direction that each of the two odometry pods count. The X (forward) pod should
        increase when you move the robot forward. And the Y (strafe) pod should increase when
        you move the robot to the left.
         */
        odo.setEncoderDirections(GoBildaPinpointDriver.EncoderDirection.FORWARD, GoBildaPinpointDriver.EncoderDirection.FORWARD);


        /*
        Before running the robot, recalibrate the IMU. This needs to happen when the robot is stationary
        The IMU will automatically calibrate when first powered on, but recalibrating before running
        the robot is a good idea to ensure that the calibration is "good".
        resetPosAndIMU will reset the position to 0,0,0 and also recalibrate the IMU.
        This is recommended before you run your autonomous, as a bad initial calibration can cause
        an incorrect starting value for x, y, and heading.
         */
        //odo.recalibrateIMU();
        odo.resetPosAndIMU();

        follower = Constants.create(hardwareMap);

        telemetry.addLine("Pedro initialized");
        telemetry.addLine("Press INIT, then PLAY to begin.");
        telemetry.update();

        telemetry.addData("Status", "Initialized");
        telemetry.addData("X offset", odo.getXOffset(DistanceUnit.MM));
        telemetry.addData("Y offset", odo.getYOffset(DistanceUnit.MM));
        telemetry.addData("Device Version Number:", odo.getDeviceVersion());
        telemetry.addData("Heading Scalar", odo.getYawScalar());
        telemetry.update();

        //robot = new HardwareITD(hardwareMap);
        rearLeft = hardwareMap.dcMotor.get("lr");
        rearLeft.setDirection(DcMotor.Direction.REVERSE);

        frontLeft = hardwareMap.dcMotor.get("lf");
        frontLeft.setDirection(DcMotor.Direction.REVERSE);

        frontRight = hardwareMap.dcMotor.get("rf");
        frontRight.setDirection(DcMotor.Direction.FORWARD);

        rearRight = hardwareMap.dcMotor.get("rr");
        rearRight.setDirection(DcMotor.Direction.FORWARD);

        rearRight.setZeroPowerBehavior(DcMotor.ZeroPowerBehavior.BRAKE);
        rearLeft.setZeroPowerBehavior(DcMotor.ZeroPowerBehavior.BRAKE);
        frontRight.setZeroPowerBehavior(DcMotor.ZeroPowerBehavior.BRAKE);
        frontLeft.setZeroPowerBehavior(DcMotor.ZeroPowerBehavior.BRAKE);

        //initialize drive motors
        frontLeft.setPower(0);
        frontRight.setPower(0);
        rearLeft.setPower(0);
        rearRight.setPower(0);

    }
    @Override
    public void init_loop() {

    }

    @Override
    public void start() {
        currentAngle = 0;
        runtime.reset();
        odo.resetPosAndIMU();
        //check whether auto saved a position
        if (OpModeStorage.autoPoseSaved == true){
            //Starting pose of teleop = ending pose of auto
            follower.setPose(OpModeStorage.autonomousEndPose);

            telemetry.addLine("Using Auto Ending Position");
        }
        else{
            //if no auto position was saved, start at field origin (audience left corner)
            follower.setPose(new Pose(0,0,0));

            telemetry.addLine("No Auto position found. Starting at 0,0,0");
        }
        telemetry.update();
    }

    @Override
    public void loop() {
        odo.update(GoBildaPinpointDriver.ReadData.ONLY_UPDATE_HEADING);

        Pose2D pos = odo.getPosition();
        telemetry.addData("Heading", pos.getHeading(AngleUnit.DEGREES));

        currentAngle = pos.getHeading(AngleUnit.DEGREES);
        follower.update();

        boolean aPressed = gamepad1.a && !prevA;
        prevA = gamepad1.a;

        boolean sticksMoved = Math.abs(gamepad1.left_stick_x) > Stick_cancel || Math.abs(gamepad1.right_stick_x) > Stick_cancel || Math.abs(gamepad1.left_stick_y) > Stick_cancel;

        if (aPressed) {
            Pose here = follower.pose();
            follower.follow(Paths.line(here, Launch_Spot).linear(here, Launch_Spot));
            autoDriving = true;
        }
        // 2. Cancel auto-drive if sticks move OR if the path finishes
        if (autoDriving && (sticksMoved || !follower.isBusy())) {
            autoDriving = false;
        }

        if (autoDriving && sticksMoved) {
            autoDriving = false;
        }
        //Handling Power Multipliers - Speed Modes
        if (!autoDriving) {
            if (gamepad1.left_bumper) {//fast mode
                powerMultiplier = 1.0;
            } else if (gamepad1.right_bumper) {//slow mode
                powerMultiplier = 0.4;
            } else {
                powerMultiplier = 0.8;//normal  q
            }

            //Getting joystick readings (Gamepad 1)
            double forward = -gamepad1.left_stick_y;
            double lateral = gamepad1.left_stick_x * 1.1; //1.1 multiplier on lateral movement for strafe adjustment
            double turn = gamepad1.right_stick_x;


            //Applying speed multipliers
            forward *= powerMultiplier;
            lateral *= powerMultiplier;
            turn *= powerMultiplier;


            // Utilize Pedro's ManualDrive.fieldCentric()
            // ManualDrive.fieldCentric() uses the robot's current heading to convert our joystick commands into the correct drivetrain commands.
            // follower.pose().heading() gives Pedro's current heading, which comes from the Pinpoint localization system.

            DrivePowers powers = ManualDrive.fieldCentric(
                    forward,
                    lateral,
                    turn,
                    follower.pose().heading()
            );


            // Send Drive Commands to Pedro. Pedro calculates the appropriate drivetrain output
            // This tells Pedro what we want the robot to do.It does not directly set individual motor powers.
            follower.manual(powers);


        }

        /////////////////////////move sequence//////////////////////////

    }
} //end of opmode






